insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 1, 'The letter P appears throughout this module. What does it stand for here?', '["A percentile of a distribution over the four terminal temperatures.", "The dimensionless temperature group formed from the four terminal temperatures.", "The pressure the shell side is rated at, in psia.", "The fraction of the design duty this exchanger delivers."]'::jsonb, 1, 'Nothing in this course is a percentile, so no percentile label belongs anywhere in it. The letter carries other meanings elsewhere on this platform, which is why the first lesson that uses it says which one applies.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 2, 'R is the second of the two groups the correction factor is written in. What is it formed from?', '["The hot stream drop over the cold stream rise.", "The cold stream rise over the span between the two inlets.", "The corrected driving force over the counter-current log mean.", "The fraction of the largest heat transfer this machine could move."]'::jsonb, 0, 'P is the cold rise over the inlet span and R is the hot drop over the cold rise. Both are pure numbers, which is what lets one correction be written for exchangers of any size.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 3, 'The studio case and ORON both have their groups out of a balance. What are they?', '["P 0.171875 and R 2.416739 on the studio case, P 0.204107 and R 2.909091 on ORON.", "P 2.909091 and R 0.171875 on the studio case, P 2.416739 and R 0.204107 on ORON.", "P 0.171875 and R 2.909091 on the studio case, P 0.204107 and R 2.416739 on ORON.", "P 0.204107 and R 2.909091 on the studio case, P 0.171875 and R 2.416739 on ORON."]'::jsonb, 2, 'The studio case is the shipped default of the live app and ORON is a four-pass exchanger with its own loop. They share nothing, so a figure from one never belongs to the other.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 4, 'The correction answer comes back on four keys. Which four?', '["The factor, the two groups it was formed from, and a warning slot that is empty on a plain answer.", "The factor, the log mean it corrects, the corrected driving force and a warning slot.", "The factor, the shell pass count, the area it implies and a warning slot.", "The factor, the shell pass count, the equivalent single-shell P and a warning slot."]'::jsonb, 3, 'The same P and R give a different factor at every shell count, so a factor without its count cannot be identified. The equivalent single-shell P is the value the closed form was actually read at.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 5, 'What is the correction factor on the studio case at one shell pass?', '["0.964693, which is what a low P buys.", "0.957197, which is the figure ORON returns at the same door.", "0.171875, which is the group the factor was computed from.", "1.000000, because a low P leaves nothing at all to correct."]'::jsonb, 0, 'ORON sits at 0.957197 on the same door, from its own groups. Neither case reaches one, because neither has a vanishing cold rise.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 6, 'The area on this engine is the duty divided by the coefficient, the factor and the log mean. What follows for the factor?', '["An error in it is absorbed by the tube count rounding before it reaches the surface.", "An error in it moves the surface only where the factor sits below one.", "An error of one percent in it is an error of one percent in the surface.", "An error in it moves the log mean by the same amount in the other direction."]'::jsonb, 2, 'Nothing stands between those three inputs and the area. That is why the factor is worth a module of its own at this tier, and why a factor read off a chart at the wrong R is expensive.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 7, 'One sweep holds R at 0.900000 and walks P upward. Where does the steep-curve warning first appear?', '["At a P of 0.520000, which is the first row where the factor falls below 0.900000.", "At a P of 0.550000, where the factor is 0.751428.", "At a P of 0.600000, where the warning appears for the first and the only time.", "At a P of 0.450000, which is the last row the engine answers with no warning."]'::jsonb, 1, 'The warning arrives on the fifth of the seven rows and stays on for the two rows above it. The four rows below it are answered with no warning at all.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 8, 'A row of that sweep comes back with the warning attached. What is the engine saying?', '["It has answered, and the factor it returned has been capped at the steepest value it will report.", "It has declined to answer, and the caller is expected to read the factor off a published chart instead.", "It has answered, and the four temperatures behind the factor sit outside the domain the closed form is written over.", "It has answered, and the curve is steep here, so a small temperature error swings the area badly."]'::jsonb, 3, 'A warning is an answer and the factor beside it is correct. The remedy the engine names is another shell pass rather than accepting a fragile number.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 9, 'At a P of 0.620000 and that same R of 0.900000 the engine stops answering. What does it return?', '["A factor lower than the one at 0.600000, with the steep-curve warning still attached.", "A factor of zero, which is how it reports a duty at the end of the curve.", "A refusal saying the configuration cannot reach this duty, and telling the caller to add a shell pass.", "A refusal saying the four terminal temperatures disagree with the duty they were given."]'::jsonb, 2, 'It does not walk off the end of the curve quietly and it does not hand back a lower factor. The step from the last warned row to the refused one is from a P of 0.600000 to a P of 0.620000.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 10, 'As P tends to zero the factor tends to one, at every R. Why is that the right answer?', '["A vanishing cold rise is a vanishing departure from counter-current flow, so nothing is left to correct.", "A vanishing cold rise makes the two end differences equal, and equal ends need no correction.", "A vanishing cold rise puts the unit on the flat part of the curve, where the correction rounds to one.", "A vanishing cold rise makes R vanish with it, and the form returns one at a zero R."]'::jsonb, 0, 'The limit is analytic, so it needs no publication behind it. A table that failed to show it would be a table with an error in it.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 11, 'One column of the limit table is evaluated by a branch written for that case alone. Which one?', '["The column at an R of 0.400000.", "The column at an R of 1.000000.", "The column at an R of 3.000000.", "The column at an R of 1.700000."]'::jsonb, 1, 'A ratio of exactly one makes the general closed form indeterminate. That branch climbs to one exactly as the four general columns do, which is a real check on both.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 12, 'The factor refuses a P of exactly one. What does that state mean physically?', '["The hot stream would be giving up no temperature at all.", "The two streams would have crossed somewhere inside the exchanger.", "The cold stream would be leaving the exchanger colder than it entered it.", "The cold stream would be leaving at the hot inlet temperature."]'::jsonb, 3, 'The message quotes the bound and the value it was handed: the factor needs a P at or above zero and below one. That is outside the domain the closed form is written over.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 13, 'And it refuses an R of zero. What does that state mean physically?', '["The hot stream would be leaving hotter than it entered.", "The shell pass count would have been given as zero.", "The hot stream would be giving up no temperature at all.", "The two streams would be entering at the same temperature."]'::jsonb, 2, 'Both bounds quote the value they were given back to the caller. That is the difference between a refusal somebody can act on and an error somebody has to guess at.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 14, 'P and R are asked for on a cold stream that leaves at the temperature it entered. What does the engine do now?', '["It refuses, saying R is undefined and that no number of shell passes changes that.", "It returns R as Infinity and lets the correction factor report the shell count as the fault.", "It returns R as zero and answers the correction factor at that value.", "It returns the groups and attaches the steep-curve warning to them."]'::jsonb, 0, 'The second half of that engine message describes what the module used to return, and it is quoted whole because shortening it would change what the engine says. The behaviour now is the refusal.'),
  ('heattransfer', 'intermediate', 'module', 'm01-p-r-and-the-correction-factor', 15, 'The published correction cases print an engine column beside a golden column. What does their agreement buy?', '["Evidence that the engine reproduces its own answer on a second call.", "Evidence about the method, because the golden column is written by the oracle on a different route.", "Evidence that the fitted constants inside the correlation were taken from a publication.", "Evidence that the factor was read at the right shell count on each row."]'::jsonb, 1, 'A golden figure is not the engine answering again. Where the two columns agree to every digit printed, two independent routes have landed on the same number.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 1, 'How does this engine rate a train of shells in series?', '["It evaluates a separate closed form written for each shell count the module carries.", "It multiplies the one shell factor by the shell count and caps the product at one.", "It converts the whole unit P into the P a single shell would see and reads the same closed form at that value.", "It marches the shells one at a time and recovers the factor from the last of them."]'::jsonb, 2, 'There is one correction form in this module. The shell count enters through the conversion rather than through a second expression, which is why the converted value is on the answer.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 2, 'Why is the equivalent single-shell P reported on a key of its own?', '["It is the value the closed form was actually read at, so a reader can see it rather than infer it.", "It is the value the whole unit would have to be brought down to in order to run at one shell pass.", "It is the value the shell count would have to be raised to before the correction factor reaches one.", "It is the value the conversion started from, before the shell count was applied."]'::jsonb, 0, 'Both numbers are called P and they are different numbers. Quoting one and calling it the other is the mistake this key exists to prevent.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 3, 'At a P of 0.720000 and an R of 0.850000, what does the engine do at one shell pass?', '["It answers with a factor of 0.541514 and attaches the steep-curve warning to it, and names two shells as the remedy.", "It answers with a factor of 0.800677, which is the value the same duty comes back with once a second shell is added.", "It refuses, saying that the equivalent single-shell P for a train of one shell works out at a value that is not a number.", "It refuses, saying the configuration cannot reach this duty and that a shell pass should be added."]'::jsonb, 3, 'Two shells answer at the same duty with a factor of 0.800677. So the first thing a second shell buys here is feasibility rather than an improvement.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 4, 'Read the equivalent single-shell P down that same sweep, from two shells to six. Which way does it go?', '["It rises, from 0.271401 at two shells to 0.541514 at six.", "It falls, from 0.541514 at two shells to 0.271401 at six.", "It holds at the whole unit value of 0.720000 at every count.", "It falls to 0.361625 at four shells and then climbs again."]'::jsonb, 1, 'Each shell in a longer train is asked for less of the total temperature change, so each one sits lower on the correction curve, where the factor is nearer one.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 5, 'And the factor itself across those counts?', '["It rises, reaching 0.981100 at six shells.", "It falls, reaching 0.800677 at six shells.", "It holds at 0.800677 from two shells upward.", "It rises to 0.956604 and then flattens exactly."]'::jsonb, 0, 'The column is entitled to say its direction and nothing more. The engine computes no ratio between two of those rows, so a figure produced by dividing one by another is one nothing here stands behind.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 6, 'The module stops the shell count at six. Where does that bound come from?', '["A published limit on shells in series, which the refusal cites.", "The largest count the published cases in this repository exercise.", "The module declares it, and the refusal says so in its own text.", "The count at which the correction factor reaches one exactly."]'::jsonb, 2, 'A published limit is a statement about the world and you argue with it by finding better data. A declared limit is a statement about the tool, and this one is labelled as declared where it is enforced.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 7, 'What reason does that refusal give for bounding the count at all?', '["The conversion loses its accuracy above six shells in series, so the factor it produces can no longer be trusted at all.", "The factor climbs toward one as shells are added, so an unbounded box makes any duty reachable by typing.", "The published cases in this repository carry no train longer than six shells, so a longer one would have no evidence behind it.", "A train longer than six would refuse on the equivalent single-shell P in any case."]'::jsonb, 1, 'The bound stops arithmetic from standing in for steel. It is a reporting decision the module owns, and it is stated where a reader meets it.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 8, 'Asked for 2.400000 shells, the engine refuses. Why does it not simply round?', '["Because the conversion inside this module is undefined at any count that is not a whole number of shells in series.", "Because the declared bound is written over whole numbers and 2.400000 falls outside it.", "Because rounding down would land on a count the same duty has already been refused at.", "Because two shells and three shells give materially different factors, so rounding would choose for the caller."]'::jsonb, 3, 'The refusal names both whole numbers either side and hands the choice back. At the duty in that lesson two shells give 0.800677 and three give 0.920456.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 9, 'At a P of 0.920000 and an R of 1.400000 the engine refuses at one shell and again at two, three and four. What changes in the message?', '["At one shell it says the configuration cannot reach the duty, and above that it reports the equivalent single-shell P as NaN.", "At one shell it reports the equivalent single-shell P as NaN, and at every count above that it names the bound this module declares.", "At one shell it names the declared bound, and above that it says the configuration cannot reach the duty.", "The message is the same at all four counts, with only the count inside it changing."]'::jsonb, 0, 'The first refusal names a remedy. The second is the engine saying the remedy has been tried and the conversion itself has nowhere to land.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 10, 'What does that second message tell a designer to stop doing?', '["Quoting the whole unit P, because only the converted value describes the train.", "Reading the factor at one shell, because the count on the answer is now four.", "Adding shells, because the shell count is no longer the variable that can reach this duty.", "Trusting the terminal temperatures, because one of them must have been mistyped."]'::jsonb, 2, 'What is left to move is the duty, the four terminal temperatures, or a different kind of exchanger. The engine says so at each count rather than once.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 11, 'A configuration that is infeasible and one that is inefficient look similar on a screen. How does this engine separate them?', '["It answers in both cases and attaches the steep-curve warning to the one that cannot reach its duty at any area.", "It answers with a warning where the curve is steep and refuses where the duty cannot be reached at any area.", "It refuses in both cases, and in the inefficient one it names the bound on the shell count that this module declares.", "It answers the infeasible case with a factor of zero and warns on the inefficient one."]'::jsonb, 1, 'A warning is an answer and the factor beside it is correct. A refusal is not an answer and there is no number in it to salvage.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 12, 'Why would the engine returning some number anyway, where the conversion did not resolve, be the worst outcome?', '["It would disagree with the golden column on that row, which is how it would be found.", "It would breach the declared bound on the shell count without saying so.", "It would be correct only at the one shell count the caller happened to ask for.", "It would look exactly like a result, carry no warning, and be quoted downstream."]'::jsonb, 3, 'That is the principle behind every refusal in this module. A default answers a question the caller did not ask and never admits that it did.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 13, 'Five of the seven published multi-shell cases sit at an R away from one. Why were they chosen that way?', '["The conversion is easiest to get wrong away from an R of one, so the general branch has to be exercised.", "The branch at an R of one is the only branch the oracle is able to march, so every other case has to be published instead.", "An R of one sits outside the domain the correction form is written over, so no case at that value could be published at all.", "Cases at an R of one are refused at every one of the shell counts this published table happens to carry."]'::jsonb, 0, 'The shell counts in that table are not all the same either. Trains of two, three and four shells appear, so the conversion is exercised at more than one count as well.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 14, 'What is the golden column in that published table evidence of?', '["The engine reproducing its own conversion on a second call made with exactly the same inputs as the first one.", "The bound of six shells being the count the published data behind those seven rows was originally taken at.", "Two routes meeting, because the oracle marches the shells and recovers the whole unit P instead of converting.", "The conversion having been transcribed correctly out of the engine and into the oracle that checks the engine."]'::jsonb, 2, 'The oracle never evaluates the conversion at all. That is what makes agreement on all seven rows worth something about the conversion.'),
  ('heattransfer', 'intermediate', 'module', 'm02-shells-in-series', 15, 'One published row runs at a P of 0.550000 and an R of 0.800000 with four shells, and returns an equivalent single-shell P of 0.219343 with a factor of 0.989954. Which of those numbers was the closed form read at?', '["0.550000, the whole unit P.", "0.219343, the converted value.", "0.800000, which the form takes as its R.", "0.989954, which the form returns."]'::jsonb, 1, 'The whole unit P is a property of the duty and the four temperatures. The converted P is a property of the train chosen to deliver it, and it is the one the correction form sees.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 1, 'The overall coefficient here is assembled rather than looked up. Which five resistances go into it?', '["The outside film, the outside fouling, the wall, the inside film and the tube metal itself.", "The outside film, the outside fouling, the wall, the inside film and the inside fouling.", "The shell film, the shell fouling, the wall, the tube film and the bundle clearance.", "The outside film, the wall, the inside film, the driving force and the reference area."]'::jsonb, 1, 'The five are named on the answer and so is each one''s share of the total. A coefficient that arrives as one figure tells you what the surface carries, and one that arrives as five tells you where to spend money.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 2, 'On the studio case the five resistances add to 0.010856543 hr.ft2.F per Btu. What is U dirty?', '["134.459410, which is one over that total.", "0.010856543, which is the total restated.", "31.495796, which is the total read as a percentage.", "92.110348, which is one over that total."]'::jsonb, 3, 'The five rows added come to 0.010856543 against the engine''s own total of 0.010856543. That addition is stated in the answer rather than left to a reader.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 3, 'U clean on the same case is 134.459410. Which terms produce it?', '["The three terms that are not fouling allowances.", "The two films, taken without the wall between them.", "The three largest terms in the resistance stack.", "The five terms with the inside pair left unconverted."]'::jsonb, 0, 'Clean means the two allowances have been left out, so the clean figure is the coefficient of a surface on the day it is commissioned. The surface a plant buys is sized on the dirty one.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 4, 'Which of the five carries the largest share of the studio stack, and how large is it?', '["The inside film, at 20.341632 percent.", "The inside fouling allowance, at 22.284762 percent.", "The outside film, at 46.055174 percent.", "The outside fouling allowance, at 9.211035 percent."]'::jsonb, 2, 'Resistances in series add, so the largest term dominates and improving a small one buys almost nothing. That is why the share column is worth as much as the resistance column.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 5, 'This coefficient is referred to one surface, and the engine says which on every answer. What does it report?', '["The outside tube surface, written out in words beside the number.", "The bore of the tube, written out in words beside the number it belongs to.", "The mean of the two tube surfaces, written on a key of its own beside the number.", "Whichever surface the larger of the two films sits on."]'::jsonb, 0, 'A second export in this engines package is also an overall coefficient and it is referred to a stated bore instead. Two different quantities on the same tube, each reporting its own reference so a value in hand can be identified.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 6, 'Why is a coefficient quoted with no reference area a number to send back rather than to use?', '["The same exchanger has two of them, and only one of the two can ever be measured.", "The same exchanger has two of them, and they differ by the ratio of the two areas.", "The reference decides whether the fouling allowances are inside the figure.", "The reference decides which of the two films the figure was assembled from."]'::jsonb, 1, 'The failure mode is not an obviously wrong answer. It is an answer that looks entirely reasonable and is wrong by the ratio of two areas, and the surface is what gets bought.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 7, 'The studio inside film coefficient is 547.762384, so one over it is 0.001825609. Why does the stack carry 0.002208398 instead?', '["The inside film has been taken at the converged tube count on this case rather than at the count the loop seeded from.", "The fouling allowance on the inside of the tube has already been folded into that same term before it is added.", "The inside terms are multiplied by the diameter ratio of 1.209677 to put them on the outside surface.", "The wall resistance is carried inside the inside film term on this engine."]'::jsonb, 2, 'The stack adds terms that have to be comparable, and a stack that mixes surfaces adds numbers that are not. The conversion is visible in the numbers rather than asserted in a comment.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 8, 'The inside fouling allowance is typed as 0.002000000 and the outside one as 0.001000000. What does the stack carry?', '["0.001000000 on the inside and 0.002419355 on the outside.", "0.002419355 on the inside and 0.002000000 on the outside.", "0.002000000 and 0.001000000, both carried unchanged.", "0.002419355 on the inside and 0.001000000 on the outside."]'::jsonb, 3, 'The inside allowance moves by the same ratio as the inside film. The outside one is already on the reference surface, so there is nothing to convert and it is carried unchanged.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 9, 'What follows for an engineer who types the same allowance on both sides of the tube?', '["The inside one carries more weight in the stack than the outside one does.", "The two carry equal weight, which is what typing them equal is for.", "The outside one carries more weight, since it needs no conversion.", "Neither carries weight until the diameter ratio has been typed as well."]'::jsonb, 0, 'That asymmetry is the most useful thing in the lesson. Two allowances typed as equals have quietly made the inside one the larger of the two.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 10, 'The engine reports a fouling penalty of 31.495796 percent on the studio case. Where else does that figure appear?', '["In the resistance column, as the two fouling terms added, at 0.001000000 and 0.002419355.", "In the share column, as the two fouling terms added, at 9.211035 and 22.284762 percent.", "In the difference between U clean and U dirty, at 134.459410 against 92.110348.", "In the controlling margin, which is reported for the same stack at 31.495796 percent."]'::jsonb, 1, 'It is an identity rather than a coincidence. One minus clean over total is the fouling terms over the total, written differently, so the penalty is never separate physics.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 11, 'What does that identity buy a reader?', '["A second published case, which this repository otherwise lacks.", "A way to recover U clean from the share column alone.", "A tolerance on the penalty, which the two routes bracket.", "Two routes to one figure, so each checks the other."]'::jsonb, 3, 'Anybody who can read the share column already knows what fouling costs this exchanger, without going near either coefficient.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 12, 'An outside fouling allowance of -0.010000000 is handed to this engine. What does it do now?', '["It answers, and reports a fouling penalty that is negative.", "It answers, and raises the dirty coefficient above the clean one.", "It refuses, saying the allowance must be zero or positive.", "It answers, and treats the allowance as zero without saying so."]'::jsonb, 2, 'The engine message also describes the behaviour the FC6-0 repair replaced, and that half is history rather than what the engine does now. Both allowances on this door are bounded at zero, and the bound is stated in the refusal.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 13, 'What is the general lesson behind bounding that input rather than watching its output?', '["An unbounded input that produces a plausible number is the dangerous case, because nobody notices it.", "An unbounded input can only ever be caught by the published cases, and they do cover this one.", "An output nobody believes is the dangerous case, because it gets quoted downstream.", "An input bounded in the code rather than in the message is the easiest one to argue with."]'::jsonb, 0, 'An obviously absurd output is the lucky case, because somebody notices it. The defence against the other one is at the input.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 14, 'The verdict on the studio stack names the outside film. What else comes with it?', '["The runner up, which on this case is the inside film, and the margin between the two of them at 46.055174 percent.", "The runner up, which is the inside fouling allowance, and the margin between them at 51.612903 percent.", "The share the leading term carries in this stack, and the coefficient the same stack would reach without that term in it.", "The runner up, and the tube count at which those two terms would change places with each other in the stack."]'::jsonb, 1, 'A verdict is a comparison and a comparison without its second place is not reportable. The engine reports three things where a simpler tool reports one.'),
  ('heattransfer', 'intermediate', 'module', 'm03-the-coefficient-from-its-parts', 15, 'Across the six cases in that table, what is the runner up?', '["A fouling allowance on all six of them.", "The wall on two of them and a film on four.", "A fouling allowance on four of them and the other film on two.", "The other film on all six of them."]'::jsonb, 2, 'Those are different situations under the same one word verdict. Reading the leading term without its runner up throws away the part that says whether to act on it.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 1, 'On the studio case the wall carries 0.000228791 hr.ft2.F per Btu. What share of the stack is that?', '["20.341632 percent, the smallest of the five terms on that case.", "2.107398 percent, the second smallest of the five terms on that case.", "9.211035 percent, the smallest of the five terms on that case.", "2.107398 percent, the smallest of the five terms on that case."]'::jsonb, 3, 'Metal conducts well and a tube wall is thin, so the term is small on almost every exchanger anybody builds. Small is a reason to check it once rather than a reason to leave it out.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 2, 'That wall table was measured at an outside diameter held at 1.000000 inches. Two things move the term across it. Which two?', '["The wall thickness and the conductivity.", "The tube count and the wall thickness.", "The conductivity and the fouling allowance.", "The tube count and the two film coefficients."]'::jsonb, 0, 'The three conductivity columns in that table stand in inverse proportion to their conductivities, so a less conductive wall moves the term by the same factor in the other direction. The outside diameter is the third thing that moves it, and holding it is what leaves only those two.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 3, 'How is the cylindrical wall resistance written on this engine?', '["The wall thickness times the logarithm of the diameter ratio, over twice the conductivity.", "The outside diameter over the bore, times the thickness, over the conductivity.", "The outside diameter times the logarithm of the diameter ratio, over twice the conductivity.", "The wall thickness over the conductivity, with no geometry in it at all."]'::jsonb, 2, 'A flat plate is the thickness over the conductivity and nothing else. The cylindrical form has to collapse onto it as the wall gets thin, because a thin enough curved wall is a flat one.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 4, 'The wall term was measured out of the engine rather than argued for on paper. How?', '["Both film coefficients were held at the studio values, so the wall is the difference.", "Both film coefficients were made negligible, so the total resistance is the wall alone.", "The conductivity was driven to zero, so the remaining terms fall out of the total.", "The tube count was driven upward until the two film terms stopped moving."]'::jsonb, 1, 'The outside diameter was held at 1.000000 inches throughout and only the thickness moved. That trick isolates any one of the five terms inside a sum.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 5, 'The ratio of the wall resistance to the flat plate runs 1.127984, 1.036724, 1.010135 and 1.002005 as the wall thins. What does that column say?', '["It approaches one from below, smoothly, which is the correct side to approach from.", "It approaches two from above, which is what the factor in the denominator predicts.", "It approaches one from above, smoothly, which is the correct side to approach from.", "It crosses one between the third row and the fourth, as the wall becomes flat."]'::jsonb, 2, 'A cylindrical wall always carries slightly more resistance than a flat plate of the same thickness. The value the column converges to is the whole content of the check.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 6, 'What would a wrong factor of two in the wall expression do to that ratio column?', '["It would converge on two or on one half, just as smoothly and just as convincingly.", "It would stop converging altogether, and the four rows would wander with no pattern in them.", "It would converge on one all the same, but from below the value rather than from above it.", "It would leave the column alone and move the studio share instead."]'::jsonb, 0, 'That is what the limit is for. The twice in the denominator is the kind of thing that gets dropped or doubled once and then lives for years.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 7, 'Why does a term carrying about two percent of a stack still deserve this check?', '["An error inside it moves the controlling verdict onto the wall term itself on this case.", "An error of a factor of two inside it leaves the coefficient close enough to look right.", "An error inside it is the one the published cases in this repository cover.", "An error inside it is carried into the area by the diameter ratio twice."]'::jsonb, 1, 'A small term is one whose value you can afford to be slightly wrong about, which is a different statement from a term you can leave out.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 8, 'Move that factor the same way in the engine and in the oracle at once. What happens?', '["The two disagree at once, which is how a moved factor is found.", "The two go on agreeing, and so does the flat plate, because the limit is a ratio.", "The oracle refuses, because it takes the wall term by quadrature.", "The two go on agreeing with each other, and neither agrees with the flat plate."]'::jsonb, 3, 'A check comparing two implementations of one expression can only find a difference between them. A shared mistake produces no difference to find.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 9, 'Three kinds of check appear in that lesson. Which can catch an error that both routes share?', '["The same expression written twice, in two files.", "A second route to the same answer, written independently.", "An analytic limit, when the limit is violated.", "A published case, when the case is at the right conditions."]'::jsonb, 2, 'The same expression written twice can find a typing error between the two copies. A second route can find an error in either route that the other does not share. Only an analytic limit sees a mistake the two of them hold in common.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 10, 'What does the oracle behind the published coefficient rows do differently from the engine?', '["It builds the stack on each term''s own area and takes the wall by quadrature.", "It builds the stack on the outside area and takes the wall by a logarithm.", "It reads the same five terms and refers them to the bore instead.", "It bisects on the coefficient until the five shares add to the total."]'::jsonb, 0, 'Its agreement with the engine is worth something, because two routes that could have differed did not. Route independence still has a limit of its own, since two routes can share an assumption.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 11, 'Several constants in this module are pinned by their literal value in the engine gate. What does a pin buy?', '["It makes the number evidence, because a review stands behind it.", "It makes changing the number a reviewed act rather than a silent one.", "It makes the number reproducible across the engine and the oracle.", "It makes the number a published figure, because the gate cites it."]'::jsonb, 1, 'Pinning a number does not make it right. Move a pinned constant in the engine and in the oracle together and every published case stays green, so on a shared constant every case green is the finding.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 12, 'This module reports whether the margin between the leading resistance and its runner up is clear. What is the threshold?', '["10 percent, taken from a publication.", "2 percent, declared by this module.", "51.612903 percent, measured on the studio case.", "10 percent, declared by this module."]'::jsonb, 3, 'It is a reporting threshold rather than a physical one. Above it the engine lets the word stand, and below it the answer carries a note instead.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 13, 'A case is built with an outside film of 0.005000000 and an inside film of 0.005100000. What does the engine report?', '["A margin of 1.960784 percent, and clear reported as yes.", "A margin of 2.0 percent exactly, and clear reported as no.", "A margin of 1.960784 percent, and clear reported as no.", "A refusal, because the two terms are too close to separate."]'::jsonb, 2, 'The note that comes with it tells the reader to treat the two as jointly controlling rather than acting on the word. The verdict is still reported and it is not hidden.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 14, 'The note for that case says 2.0 percent and the margin key says 1.960784. Which is which?', '["The note is prose written for a reader, and the key is the value to compute with.", "The note carries the margin at full precision and the key carries it rounded.", "The note is the declared threshold and the key is the margin measured against it.", "The note is the margin on the leading term and the key is the margin on the runner up."]'::jsonb, 0, 'A message written for a human and a value written for a caller have different jobs. A tool returning only the message forces every caller to parse a sentence to recover a number.'),
  ('heattransfer', 'intermediate', 'module', 'm04-the-wall-and-a-limit-that-fixes-a-factor', 15, 'Compare that near case against the studio case, where the margin is 51.612903 percent. What differs?', '["The number of resistances the two stacks were assembled from.", "The confidence behind the same kind of one word verdict.", "The threshold each of the two cases is measured against.", "Which of the two coefficients the verdict was taken on."]'::jsonb, 1, 'A reader given only the leading term would treat the two cases identically. That is why the margin is on the answer, and why the engine says whether it is clear.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 1, 'The film correlation here takes two dimensionless arguments. Which two, and who owns the first as a subject?', '["A Reynolds number and a Nusselt number, and the Reynolds number belongs to the Rotating Equipment module.", "A Prandtl number and a capacity ratio, and the capacity ratio belongs to Pipeline and Line Sizing.", "A Reynolds number and a Prandtl number, and the Reynolds number belongs to Pipeline and Line Sizing.", "A Reynolds number and a Prandtl number, and the Reynolds number is derived from scratch here."]'::jsonb, 2, 'This course does not re-derive a Reynolds number. It is an argument to a correlation, and it is reported on the answer so it can be checked against whatever source a reader trusts.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 2, 'At the studio converged count of 74 tubes in 2 passes, what does the film call return?', '["Reynolds 44051.846000, Prandtl 15.119375, turbulent, and a film coefficient of 547.762384.", "Reynolds 44051.846000, Prandtl 15.119375, laminar, and an inside film coefficient of 547.762384.", "Reynolds 45275.508389, Prandtl 15.119375, turbulent, and an inside film coefficient of 559.901439.", "Reynolds 44051.846000, Prandtl 12.678930, turbulent, and a film coefficient of 994.597468."]'::jsonb, 0, 'That is 37 tubes a pass. The answer carries ten keys in all, and those four are the ones a reader quotes first.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 3, 'What happens to the Prandtl number as the tube count moves along the studio trail?', '["It falls with the Reynolds number, because both are formed from the velocity.", "Nothing, because it is a property of the fluid rather than of the bundle.", "It rises as the count rises, which is what holds the film up at high counts.", "It is recomputed at each count and reported only at the converged one."]'::jsonb, 1, 'It stays at 15.119375 at every count on that trail. So everything the geometry does to the film arrives through the Reynolds number alone.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 4, 'Read the studio trail at 2, 60, 72 and 74 tubes. Which way do the Reynolds number and the area go?', '["The Reynolds number rises and the area falls, to 185.448625 ft2.", "Both fall, and the area ends at 185.448625 ft2 once the loop has closed.", "Both rise, and the area ends at 229.543151 ft2 once the loop has closed.", "The Reynolds number falls and the area rises, from 185.448625 to 229.543151 ft2."]'::jsonb, 3, 'The same flow divided among more tubes moves more slowly in each of them. The film falls with the Reynolds number, the coefficient falls with the film, and the area the coefficient asks for rises.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 5, 'The first row of that trail is 2 tubes at a Reynolds number of 1629918.301989. What is that row?', '["A step on the trail the iteration left behind, rather than an answer.", "The answer at the seed the studio ladder starts from, which is 2 tubes.", "The bundle the engine recommends before the fouling allowances are applied.", "The count at which the film is highest, so it is the count worth designing at."]'::jsonb, 0, 'Two tubes carry the whole flow, so its film coefficient of 9843.591536 belongs to a bundle nobody would build. Only the last row of the trail describes a real exchanger.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 6, 'Three regimes, three treatments. What does the engine do in each?', '["It refuses below 2300, warns inside the band, and answers above 10000.", "It warns below 2300, answers between 2300 and 10000, and refuses above 10000.", "It warns below 2300, refuses between 2300 and 10000, and answers plainly above 10000.", "It answers below 2300, refuses between 2300 and 10000, and warns above 10000."]'::jsonb, 2, 'Both band edges are declared constants of this module, so a reviewer finds them in one place rather than in a comparison buried in the arithmetic, and the refusal quotes them back in its own message.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 7, 'The film is asked for at 6000.0000 lb an hour on the studio bundle and refused. What comes back beside the message?', '["A Reynolds number of 3303.888450, and the film coefficient the laminar limit would have given at it.", "A Reynolds number of 3303.888450, a Prandtl number of 15.119375, and 37.000000 tubes a pass.", "A Reynolds number of 6607.776900, a Prandtl number of 15.119375, and the whole tube count of the bundle.", "The two band edges and the flow that would be needed to clear the upper one."]'::jsonb, 1, 'A refusal carrying only its message would leave a caller with no idea how far inside the band they were. This one hands back the numbers that produced the state it refused.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 8, 'That refusal names three inputs to change. Which three, and why those?', '["The flow, the duty or the fouling allowance, because all three of them move the film coefficient.", "The tube count, the passes or the flow, because all three move the Prandtl number.", "The bore, the wall conductivity or the length, because all three move the geometry.", "The tube count, the passes or the bore, because all three move the velocity inside a tube."]'::jsonb, 3, 'The band is a property of the velocity rather than of the duty, so the remedy is geometry. A number produced in that band would be a confident figure with nothing behind it.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 9, 'Why does the studio walk a ladder of seeds rather than starting the loop from one guess?', '["An intermediate count can land the film inside the band the engine refuses.", "A single seed converges on a different count from the one the ladder reaches.", "The first seed on the ladder is the published count.", "A single seed cannot be checked against the trail the iteration leaves."]'::jsonb, 0, 'A seed that refuses is a seed the loop cannot start from, and the ladder gives it somewhere else to begin. The first seed that evaluates is the one the loop runs from.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 10, 'At 900.0000 lb an hour the Reynolds number is 495.583267 and the film is 5.667097. Double the flow. What is the film?', '["5.667097, at a Reynolds number of 1431.684995.", "5.667097, at a Reynolds number of 495.583267.", "345.692714, at a Reynolds number of 991.166535.", "5.667097, at a Reynolds number of 991.166535."]'::jsonb, 3, 'The constant wall temperature laminar limit is a statement about the shape of the temperature profile in a fully developed flow, and the flow rate has dropped out of it. Nothing is broken and nothing has been rounded.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 11, 'The laminar warning states three things. Which three?', '["The film does not move with the flow rate, the transition band edge is nearby, and entrance effects are ignored here.", "The film sits below the transition band, the correlation behind it is fitted, and the tube count may yet change it.", "The film does not move with the flow, the viscosity correction is not applied, and entrance effects are ignored.", "The film does not move with the bore, the viscosity correction is applied, and the answer is a limit."]'::jsonb, 2, 'All three are limitations rather than results. Entrance effects are real and can matter a great deal in a short tube, and they are outside what this limit describes.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 12, 'Why does the engine warn in the laminar range and refuse in the transition band?', '["In the laminar range the correlation behind the answer is a fit, and inside the band that same fit is extrapolated.", "In the laminar range there is a limit with a clean derivation behind it, and in the band there is nothing.", "In the laminar range the Reynolds number is reported, and in the band it is not.", "In the laminar range the flow is known, and in the band the tube count is not."]'::jsonb, 1, 'So a number exists in the one case that is worth returning. The warning stops it from being read as more than it is.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 13, 'The Sieder-Tate correction is applied on one condition. What is it, and what does it do on the studio case?', '["A wall viscosity is given, and at 0.320000 cp the factor is 1.064473 and the film 583.078474.", "The flow is turbulent, and at a wall viscosity of 0.320000 cp the factor is 1.000000 and the film 547.762384.", "The service is heating, and at a wall viscosity of 0.320000 cp the factor is 1.064473 and the film 547.762384.", "A wall viscosity is given, and at 0.320000 cp the factor is 1.209677 and the film 583.078474."]'::jsonb, 0, 'The answer reports which of the two happened rather than leaving a reader to infer it from the number. With no wall viscosity given the factor is 1.000000 and the film is 547.762384.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 14, 'What does the correlation block report for the validity band of this fit?', '["The two transition band edges, which are the band it was fitted over.", "The band in Reynolds only, because the Prandtl band is not established.", "Null, with the Reynolds and Prandtl numbers handed over beside it.", "The band the published film cases in this repository were taken across."]'::jsonb, 2, 'The engine cannot tell you whether you are inside the band, so it hands over the two numbers a reader would need to find out from a source they have and it does not. Nothing here grades them.'),
  ('heattransfer', 'intermediate', 'module', 'm05-the-tube-side-film', 15, 'A tube side declared as cooling is refused. What does the refusal say the difference is worth?', '["About 31 percent on the log mean driving force at a Prandtl around 15.", "About 31 percent on the inside film at any Prandtl number at all.", "Nothing on the inside film until the flow reaches the transition band.", "About 31 percent on the inside film at a Prandtl around 15."]'::jsonb, 3, 'The studio case has a Prandtl number of 15.119375, so that is the neighbourhood the statement is about. The refusal tells the caller to type the tube-side film instead of computing it.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'The chain on this engine is a loop rather than a line. What needs what?', '["The film needs the area, the area needs the count, the count needs the duty, and the duty needs the film.", "The film needs the count, the count needs the area, the area needs the coefficient, the coefficient needs the film.", "The coefficient needs the count, the count needs the film, the film needs the duty, the duty needs the area.", "The area needs the film, the film needs the coefficient, the coefficient needs the duty, the duty needs the count."]'::jsonb, 1, 'A map like that is a contraction, so plain iteration settles it. A coefficient computed at a tube count the same screen contradicts is not a coefficient of anything.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'What is the tube count trail on the studio case, and how many passes of the loop does it take?', '["2, 12, 60 and 300 tubes, converged in 4 passes.", "4, 56 and 64 tubes, converged in 3 passes.", "2, 60, 72 and 74 tubes, converged in 2 passes.", "2, 60, 72 and 74 tubes, converged in 4 passes."]'::jsonb, 3, 'The ladder of seeds the studio walks is 2, 12, 60 and 300 tubes, and the first seed that evaluates starts the loop. The trail is what the loop left behind on the way to the answer.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'ORON runs the same chain on a four-pass bundle. What ladder of seeds does it walk?', '["4, 24, 120 and 600 tubes.", "2, 12, 60 and 300 tubes.", "4, 56 and 64 tubes, which are also the counts it settles through.", "2, 60, 72 and 74 tubes, one seed for each pass of the loop."]'::jsonb, 0, 'A ladder is where the iteration may start and a trail is where it went. ORON settles through 4, 56 and 64 tubes in three passes, and the studio case shares none of those figures.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'At the converged count, the coefficient times the area times the correction times the log mean comes to 2750000.0000 Btu an hour. What is that?', '["A second method, because the product uses the area and the duty did not.", "A published check, because the golden file carries that product.", "A self-consistency check, against a duty of 2750000.0000 Btu an hour.", "A restatement of the duty, since the area was formed from it and nothing else."]'::jsonb, 2, 'It is the check that catches a loop that has not closed. Four figures at the end of the chain either satisfy the equation they were built from or they do not.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'The studio case takes no correction on its arrangement. What is the driving force the surface is sized on?', '["The arithmetic mean of the two ends, at 130.064846 degF.", "The counter-current log mean itself, at 130.064846 degF.", "The counter-current log mean corrected by 0.964693.", "The parallel log mean, at 130.064846 degF."]'::jsonb, 1, 'The two groups on this case are low, at a P of 0.171875 and an R of 2.909091. The area then follows from the duty, the coefficient and that driving force.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'The area required on the studio case is 229.543151 ft2 and the actual surface is 232.477856 ft2. What is the overshoot and why is it there?', '["1.278498 percent, because the count is rounded up to the nearest ten tubes.", "2.107398 percent, because a whole number of tubes cannot land exactly on a required area.", "1.278498 percent, because the area carries the ten percent margin this module declares.", "1.278498 percent, because a whole number of tubes cannot land exactly on a required area."]'::jsonb, 3, 'The count is 74 tubes in 2 passes, which is 37 a pass. The overshoot is reported rather than left for a reader to notice.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Two coefficients come out of the stack on this case. Which one sizes the surface a plant buys?', '["U dirty, at 92.110348.", "U clean, at 134.459410.", "U dirty, at 134.459410.", "Whichever of the two the fouling penalty is nearer."]'::jsonb, 0, 'The exchanger has to do its duty when it is dirty. U clean, at 134.459410, is what the surface will carry on the day it is commissioned.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Of the figures in the studio chain, which one did a fitted correlation produce?', '["The overall coefficient.", "The log mean driving force.", "The inside film coefficient.", "The correction factor."]'::jsonb, 2, 'The outside film and the wall conductivity on this case are stated inputs. The inside film is the one quantity a correlation produced, and that correlation is the module''s only fitted one, which is the reason the graded work in this course states both films.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Why does this course state both film coefficients wherever a coefficient is worked?', '["So that the inside film coefficient need not be recomputed at every tube count along the trail the loop leaves.", "So that no figure a reader produces rests on a fit whose validity band nobody here can state.", "So that the two film coefficients can be typed as equals and the allowances beside them compared directly.", "So that the coefficient can be referred to either surface without converting."]'::jsonb, 1, 'Nothing in this course grades a film coefficient. A figure a reader is asked to produce should rest on conditions of the case rather than on a fitted correlation.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'What has to be quoted beside a film coefficient, and what beside an overall coefficient?', '["The Reynolds number beside the film coefficient, and the fouling penalty beside the overall coefficient.", "The regime beside the film, and the controlling term beside the coefficient.", "The passes beside the film, and the tube count beside the coefficient.", "The tube count and the passes beside the film, and the reference area beside the coefficient."]'::jsonb, 3, 'A film coefficient without its count belongs to no bundle, and a U without its reference area belongs to no surface. Both are quoted at the precision the engine prints them at.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'A capstone question asks for a figure the engine declines to give. What is the right answer?', '["The decline itself, because writing a plausible figure into that gap is a wrong answer.", "The nearest figure the engine does give at another configuration, with the decline noted beside it.", "A figure worked by hand out of the conditions the question states, since they are all given.", "The figure at the nearest configuration the engine will answer at, with the change written down."]'::jsonb, 0, 'A configuration that cannot reach its duty at one shell is refused by name, and so are a count past the declared bound, a fractional count, a film in the transition band and a cooled tube side. The gap was the point of the question.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'A multi-shell question carries two numbers called P. How are they told apart?', '["One is the whole unit value and the other is that same value once the correction factor has been applied to it.", "One is the cold rise over the span between the two inlets and the other is the hot drop over that same cold rise.", "One comes off the four temperatures and the other is what the conversion produces at the stated shell count.", "One is reported by the engine and the other is worked out by the caller."]'::jsonb, 2, 'The equivalent single-shell P is the value the closed form is read at. Confusing the two is the commonest way to lose a mark on a multi-shell question.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Which of the six capstone quantities can be read straight off the share column, with no coefficient in hand?', '["U clean, as the three terms that are not fouling allowances taken as a share of the total.", "The fouling penalty, as the two fouling terms taken as a share of the total.", "The equivalent single-shell P at two shells, as the leading share of the whole unit P.", "The correction factor, as the share the corrected driving force keeps of the log mean."]'::jsonb, 1, 'If the two routes disagree, something upstream of both is wrong, and it is usually an inside term put into the stack without the diameter ratio on it.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'At what precision does this course quote a resistance, and at what precision a duty?', '["Six decimals for a resistance, and four for a duty in Btu an hour.", "Nine decimals for a resistance, and six for a duty in Btu an hour.", "Four decimals for a resistance, and nine for a duty in Btu an hour.", "Nine decimals for a resistance, and four for a duty in Btu an hour."]'::jsonb, 3, 'Quote a figure at the precision the engine prints it rather than rounding on the way. A rounded restatement of an engine answer cannot be told apart from a number somebody invented.'),
  ('heattransfer', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'This tier asked what decides the driving force and what decides the coefficient. What does the Expert tier ask instead?', '["What surface a stated duty asks for on a longer train.", "What the shell side film coefficient works out at.", "What a machine that already exists delivers.", "What a bundle costs once its shell diameter is known."]'::jsonb, 2, 'Both questions here are sizing questions, and they start from a duty and end with a surface. A rating starts from a machine, and it is answered in a different currency.'),
  ('heattransfer', 'intermediate', 'final', null, 1, 'Three quantities stand under the duty when this engine sizes a surface. Which three?', '["The overall coefficient, the tube count and the log mean driving force.", "The two film coefficients and the log mean driving force.", "The overall coefficient, the correction factor and the log mean driving force.", "The overall coefficient, the correction factor and the arithmetic mean of the two ends."]'::jsonb, 2, 'Two of those three are what this tier is about. An error in any one of them arrives in the area unchanged, and the area is what gets bought.'),
  ('heattransfer', 'intermediate', 'final', null, 2, 'What question do P and R exist to answer?', '["How far from counter-current flow the arrangement sits.", "How much of the duty the shell side is carrying.", "How far the coefficient sits below its clean value.", "How much surface the duty will need at this coefficient."]'::jsonb, 0, 'A shell and tube unit with one shell pass and two tube passes runs partly counter-current and partly parallel, so its true driving force sits below the counter-current log mean. The factor is that shortfall as a multiplier.'),
  ('heattransfer', 'intermediate', 'final', null, 3, 'The groups door hands back two keys and no more. What are they?', '["P and the correction factor.", "P and R.", "R and the log mean.", "P and the equivalent single-shell P."]'::jsonb, 1, 'The correction factor is a separate call and it carries four keys of its own. Reading the pair before anything downstream is what the groups are for.'),
  ('heattransfer', 'intermediate', 'final', null, 4, 'Of the two teaching exchangers, which sits lower on the correction curve at one shell pass?', '["The studio case, at 0.964693.", "ORON, at 0.204107.", "The studio case, at 0.171875.", "ORON, at 0.957197."]'::jsonb, 3, 'Neither reaches one, because neither has a vanishing cold rise. The two cases share nothing else, so a figure from one never belongs to the other.'),
  ('heattransfer', 'intermediate', 'final', null, 5, 'Walking P upward at a fixed R of 0.900000 produces three kinds of return in order. Which order?', '["An answer, then a refusal, then an answer with a warning.", "An answer with a warning, then an answer, then a refusal.", "An answer, then an answer with a warning, then a refusal.", "An answer, then a warning with no factor, then a refusal."]'::jsonb, 2, 'The factor falls as P rises and it falls faster the further up the sweep it is read. The engine never walks off the end of the curve quietly.'),
  ('heattransfer', 'intermediate', 'final', null, 6, 'High on that curve the four terminal temperatures are measurements. What does the warning say a small error in one of them costs?', '["A badly swung area, because the factor moves enough up there to change the tube count.", "A badly swung log mean, because the warning is attached to the driving force rather than to the factor.", "Nothing at all yet, because the factor is capped by this module before the area is ever formed.", "A refusal, because the sweep is one row below the unreachable configuration."]'::jsonb, 0, 'The four temperatures behind a factor are measurements. Low on the curve an uncertainty in one of them is harmless, and high on it the same uncertainty turns into a surface the plant falls short of.'),
  ('heattransfer', 'intermediate', 'final', null, 7, 'Why does the limit at a vanishing P need no publication behind it?', '["It is measured, and the measurement is in the published case file.", "It is analytic, so nobody has to have measured an exchanger for it to be right.", "It is declared by this module, like the bound on the shell count.", "It is fitted, and the fit is pinned by literal in the engine gate."]'::jsonb, 1, 'It also discriminates. A wrong constant anywhere in the closed form shows up as a column that fails to climb, or climbs to something other than one.'),
  ('heattransfer', 'intermediate', 'final', null, 8, 'One column of the limit table is reached by a branch of the closed form written for that case alone, and it climbs to one as the others do. What does that agreement check?', '["The general branch only, since the special one is a special case of it.", "The special branch only, since the general one is checked by the published cases.", "Neither, since a function agreeing with itself at a limit is an identity.", "Both branches, because each has to satisfy the same limit."]'::jsonb, 3, 'A ratio of exactly one makes the general form indeterminate. If the special branch carried the wrong sign or the wrong grouping, its column would part company with its neighbours on the way down.'),
  ('heattransfer', 'intermediate', 'final', null, 9, 'Which refusal in this tier hands back the numbers that produced the state it refused?', '["The correction factor at a P of 0.620000, which returns the equivalent single-shell P.", "The tube-side film inside the transition band, which returns the Reynolds number.", "The shell count at seven, which returns the factor the sixth shell would have given.", "The wall conductivity at zero, which returns the flat plate value at that thickness."]'::jsonb, 1, 'Three of the twelve doors on this engine hand back more than a message, and the film is the one in this tier. A panel that shows only the message throws that evidence away.'),
  ('heattransfer', 'intermediate', 'final', null, 10, 'What is the difference between a bound a module declares and a limit a publication carries?', '["You argue with a declared one by finding better data, and with a published one by reviewing the code it sits in.", "A declared one is enforced by a refusal that names it, and a published one is enforced by a warning on the answer.", "A declared one is checked by the golden file and a published one is checked by an analytic limit.", "You argue with a declared one by reviewing the declaration and with a published one by finding better data."]'::jsonb, 3, 'A limit that hides in a comparison somewhere in the code cannot be argued with at all, because nobody can find it. This module carries a declared bounds table and names the bound as declared where it enforces one.'),
  ('heattransfer', 'intermediate', 'final', null, 11, 'Two entries in that declared bounds table come up in this tier. Which two?', '["The shell count stopping at six, and the transition band running from 2300 to 10000.", "The margin at which a controlling resistance is named, and the fouling allowance floor at zero.", "The shell count stopping at six, and the margin at which a controlling resistance is named.", "The transition band edges, and the tube passes the bundle constants are carried for."]'::jsonb, 2, 'Both are reporting decisions rather than physics and both are labelled. The band edges are declared constants of the module, on a separate table from the bounds.'),
  ('heattransfer', 'intermediate', 'final', null, 12, 'One duty is refused at one shell and answered at two. Another is refused at one, two, three and four. What separates the two cases?', '["The first sits inside the declared bound on the shell count and the second sits outside it.", "The first is reachable once a shell is added, and the second is reachable at no count that was tried.", "The first carries the steep-curve warning on its answer and the second carries none at all.", "The first is refused by the conversion and the second by the bound this module declares."]'::jsonb, 1, 'The first case runs at a P of 0.720000 and an R of 0.850000, and the second at a P of 0.920000 and an R of 1.400000. A configuration can be infeasible rather than merely inefficient.'),
  ('heattransfer', 'intermediate', 'final', null, 13, 'A tool that quietly rounded a request for 2.400000 shells would be worse than one that refuses. Why?', '["The caller would be handed a train longer than the declared bound allows.", "The caller would get a factor from a branch of the form written for whole counts.", "The caller would never learn that a choice had been made on their behalf.", "The caller would lose the equivalent single-shell P from the answer."]'::jsonb, 2, 'Rounding down would hand back 0.800677 and rounding up 0.920456. Those are materially different factors, so the engine makes the caller choose.'),
  ('heattransfer', 'intermediate', 'final', null, 14, 'What does the golden column beside those multi-shell rows tell you that a second copy of the engine could not?', '["That a route which never evaluates the conversion reaches the same seven answers.", "That the conversion in this module was transcribed into the oracle beside it without a typing error in it.", "That the seven rows in that table were taken from a publication on trains of shells in series.", "That the bound of six shells this module declares was the count the published data was gathered at."]'::jsonb, 0, 'The oracle marches the shells in series and recovers the whole unit P from the march. Where a route could only have been a transcription, the golden file would tell you the two files agree and nothing more.'),
  ('heattransfer', 'intermediate', 'final', null, 15, 'Why is a coefficient assembled from five named parts worth more than the same coefficient as one figure?', '["The parts can be referred to either surface, while the figure cannot.", "The parts are graded in this course, while the figure is not.", "The parts carry the fouling allowances, while the figure leaves them out.", "The parts say which side of the tube is worth spending money on."]'::jsonb, 3, 'A stack whose parts are visible turns a coefficient into a decision. Money spent on a term that carries a small share of it cannot move the answer far, and the share column is what says so before anybody prices the work.'),
  ('heattransfer', 'intermediate', 'final', null, 16, 'The word series in that title is doing real work. What follows from it for the wall on the studio case?', '["At 2.107398 percent of the stack, the wall is the term to leave out of the sum.", "At 2.107398 percent of the stack, a better alloy is a poor use of money there whatever it costs.", "At 2.107398 percent of the stack, the wall sets the margin on the controlling verdict.", "At 2.107398 percent of the stack, the wall is the term the fouling allowance is compared against."]'::jsonb, 1, 'The share column is worth as much as the resistance column, because it says what a term is worth improving before anybody prices the improvement.'),
  ('heattransfer', 'intermediate', 'final', null, 17, 'Two exports in this engines package are called an overall coefficient. What separates them?', '["The number of named resistances each of the two is assembled from.", "Whether the two fouling allowances are inside the figure or left out of it.", "The surface each one is referred to, which each of them reports.", "Whether the answer carries a controlling term and a margin."]'::jsonb, 2, 'One of them belongs to this module and the other to the production domain. A duty through a wall is fixed by physics, and what changes with the convention is how that duty is written down.'),
  ('heattransfer', 'intermediate', 'final', null, 18, 'A coefficient taken from one reference convention and used in the other is wrong by the ratio of two areas. Why is that dangerous rather than obvious?', '["The answer looks entirely reasonable, and it carries straight into the surface.", "The answer is refused by the engine, so the work stops and the whole case has to be retyped.", "The answer moves the controlling verdict onto the wall, where nobody checks it.", "The answer is off by a factor of two, which reads as a unit error."]'::jsonb, 0, 'That is why the first question about any coefficient is which area it belongs to, and the second is whether the area it is about to be multiplied by is that one.'),
  ('heattransfer', 'intermediate', 'final', null, 19, 'The inside terms are converted onto the reference surface and the outside fouling allowance is not. What decides which?', '["Whether the term is a film coefficient or a fouling allowance.", "Whether the term was typed by the caller or computed by the engine.", "Whether the term is larger than the wall resistance in the same stack.", "Whether the term already sits on the surface the stack is referred to."]'::jsonb, 3, 'The wall is a third case again. Its expression already carries the geometry inside it, so there is nothing to refer afterwards. Three terms, three treatments, one reference surface.'),
  ('heattransfer', 'intermediate', 'final', null, 20, 'How can a reader check the diameter ratio conversion on the screen rather than trusting it?', '["Take the ratio of the two fouling allowances as typed.", "Take one over the film coefficient and divide the printed resistance by it.", "Divide U clean by U dirty and compare against the printed penalty.", "Take the outside film share over the inside film share."]'::jsonb, 1, 'The engine prints both ends of that conversion. A conversion nobody checks has been right for years or wrong for years, and the two look identical from a distance.'),
  ('heattransfer', 'intermediate', 'final', null, 21, 'What does the fouling penalty of 31.495796 percent on the studio case mean for a surface?', '["The exchanger is sized on the clean coefficient and then derated by that percentage once it is in service.", "The exchanger is sized on the mean of the two coefficients, and that penalty is what sets where the mean sits.", "The exchanger is sized on the dirty coefficient, and the clean one is what it carries when new.", "The exchanger is sized on the dirty coefficient, and the penalty is the margin carried above the surface asked for."]'::jsonb, 2, 'Clean is what it will do on its first afternoon, and what it will stop doing within weeks. The penalty is also the two fouling terms as a share of the total, which is an identity rather than a coincidence.'),
  ('heattransfer', 'intermediate', 'final', null, 22, 'Where does the defence against an input nobody bounded belong?', '["At the input, since an unbounded one can produce a figure that looks perfectly sensible.", "At the output, since a figure that looks sensible will still fail a published case.", "At the golden file, since a second route disagrees wherever an input is unbounded.", "At the gate, since a pinned constant cannot be moved without a review."]'::jsonb, 0, 'Watching the output only works while the output is absurd enough for somebody to notice, and the absurd one is the lucky case.'),
  ('heattransfer', 'intermediate', 'final', null, 23, 'Which of the five resistances does a designer choose outright?', '["The two film coefficients.", "The wall and the outside film.", "The inside film and the wall.", "The two fouling allowances."]'::jsonb, 3, 'The outside film arrives as an input and the inside one is computed or typed, but neither is a choice in the way an allowance is. The allowances are what the fouling penalty is the cost of.'),
  ('heattransfer', 'intermediate', 'final', null, 24, 'This repository carries no published heat exchanger case for the wall term. What stands in for one?', '["A published case from a neighbouring module, converted into these units.", "Route independence, the constant pins and the analytic limits.", "The agreement of the engine and its oracle.", "The studio case, which a reader can check against the live app."]'::jsonb, 1, 'The golden file is declared synthetic and says so rather than dressing an invented row as a citation. The limits are the strongest of the three, because they can catch a mistake the two routes share.'),
  ('heattransfer', 'intermediate', 'final', null, 25, 'Both films were made negligible to measure the wall term. What does that technique do in general?', '["It removes the reference area from the answer, so the term needs no conversion.", "It drives the controlling verdict onto the term under test, which names it.", "It isolates one term inside a sum of five, so the answer is a reading of that term.", "It replaces the published case the repository does not carry for that term."]'::jsonb, 2, 'The outside diameter was held at 1.000000 inches throughout and only the thickness moved, so nothing but the variable of interest changed between rows. The same trick works on any of the five.'),
  ('heattransfer', 'intermediate', 'final', null, 26, 'The ratio of the wall resistance to the flat plate reaches 1.002005 at the thinnest wall in that table. What is the finding?', '["The value the column converges to, rather than how close the last row gets.", "The rate the column converges at, which fixes the factor in the denominator.", "The agreement at the thickest wall, which is where the two forms differ most.", "The sign of the difference, which tells you which of the two forms is wrong."]'::jsonb, 0, 'An expression with a wrong factor of two would converge just as smoothly, on two or on one half. That is what makes this limit a check on a factor nobody can inspect.'),
  ('heattransfer', 'intermediate', 'final', null, 27, 'Two analytic limits stand behind this tier: the factor tending to one at a vanishing P, and a thin wall collapsing onto a flat plate. What do they have in common?', '["Each is measured out of the published case file, which is why they need no citation.", "Each can be checked with no citation in hand, and each discriminates against a shared error.", "Each is pinned by literal in the engine gate, so moving one is a reviewed act.", "Each is declared by this module, like the bound on the shell count."]'::jsonb, 1, 'This repository carries no published heat exchanger case, so the golden file is declared synthetic and says so. What stands in for published data is route independence, the constant pins, and limits of this kind.'),
  ('heattransfer', 'intermediate', 'final', null, 28, 'How far ahead does the leading resistance have to be before its name stands on its own here?', '["2 percent of itself.", "10 percent of the whole stack.", "10 percent of itself.", "More than the runner up carries of the whole stack."]'::jsonb, 2, 'A one word verdict decided by a narrow gap is a coin toss wearing the clothes of a result. The figure is a reporting decision this module owns and no publication carries it.'),
  ('heattransfer', 'intermediate', 'final', null, 29, 'Why does this module apply that comparison itself rather than printing the margin and leaving it to a reader?', '["A word on a screen is read and acted on, and a percentage beside it is noticed by whoever was already going to check.", "A margin printed alone cannot be compared against a threshold that is declared.", "A reader cannot see the runner up, so the comparison would have no second term.", "A margin printed alone would have to be recomputed from the shares every time."]'::jsonb, 0, 'A declared threshold turns that check into something the tool does every time, which is the only version of a check that survives a busy afternoon.'),
  ('heattransfer', 'intermediate', 'final', null, 30, 'A coefficient answer arrives with the note about a narrow margin attached. What does the note ask a reader to do?', '["Take the leading term and act on it, since the engine still names one.", "Discard the verdict, since the margin sits under the declared threshold.", "Re-run the stack at another tube count.", "Treat the leading term and its runner up as jointly controlling."]'::jsonb, 3, 'The module does not hide the verdict and it does not pretend it is sharper than the numbers behind it. Above the margin it declares, the word is left to stand on its own.'),
  ('heattransfer', 'intermediate', 'final', null, 31, 'Sweep the flow through one studio bundle at 45000.0000, 120000.0000 and 400000.0000 lb an hour. What do the Reynolds number and the film do?', '["Both fall, from 220259.229998 and 1985.035182 to 24779.163375 and 345.692714.", "Both rise, from 24779.163375 and 345.692714 to 220259.229998 and 1985.035182.", "The Reynolds number rises and the film holds at 5.667097 across all three.", "The Reynolds number rises and the film falls, as it does along the tube count trail."]'::jsonb, 1, 'The three rows are read for direction only. This course prints no ratio between them, because the engine computes none.'),
  ('heattransfer', 'intermediate', 'final', null, 32, 'Which single number on a film answer decides which of the three treatments produced it?', '["The Reynolds number.", "The Prandtl number of the fluid.", "The tubes a pass on the bundle.", "The wall viscosity, when one is given."]'::jsonb, 0, 'Below 2300 the laminar limit is used and the answer is warned about, above 10000 the turbulent fit answers plainly, and between the two the engine refuses. The Prandtl number is a property of the fluid and it does not move with the bundle at all.'),
  ('heattransfer', 'intermediate', 'final', null, 33, 'A film coefficient that does not move when the flow is doubled. What is happening?', '["The answer has been capped at the value the transition band edge would give.", "The correlation has been evaluated at the same Reynolds number twice.", "The laminar constant wall temperature limit is being used, and the flow has dropped out of it.", "The Sieder-Tate correction has absorbed the change in the flow."]'::jsonb, 2, 'Nothing is broken and nothing has been rounded. Every laminar answer carries a warning that says so in advance, along with the two other limitations that come with the limit.'),
  ('heattransfer', 'intermediate', 'final', null, 34, 'A laminar tube side will not improve by pushing more fluid through the same bundle. What does that leave a designer?', '["Changing the pump, until the flow crosses into the transition band.", "Changing the fouling allowances, which move the coefficient instead.", "Changing the service to heating, which takes the correction the limit declines.", "Changing the geometry, which is the tube count, the passes or the bore."]'::jsonb, 3, 'Those are the same three inputs the transition refusal names, and for the same reason. The regime is a property of the velocity inside a tube.'),
  ('heattransfer', 'intermediate', 'final', null, 35, 'A caller gives a wall viscosity of 0.320000 cp on the studio case. What happens to the film?', '["It is corrected by 1.209677, to 583.078474.", "It is corrected by 1.064473, to 583.078474.", "It is left at 547.762384, because the correction needs a turbulent regime.", "It is corrected by 1.064473, to 547.762384."]'::jsonb, 1, 'The factor is reported on a key of its own, so the two film coefficients can be told apart by a reader holding only one of them. A correction folded silently into a result is a correction nobody can audit.'),
  ('heattransfer', 'intermediate', 'final', null, 36, 'What does the engine hand a reader in place of a validity band it cannot state?', '["The Reynolds and Prandtl numbers, on every call, so they can be checked elsewhere.", "The two transition band edges, which bracket where the fit is trustworthy.", "The published film cases, which are the band the fit was taken over.", "A warning on every answer that the fit may be extrapolated."]'::jsonb, 0, 'That is the honest shape for a held item. Name the gap, hand over what a reader needs to close it themselves, and grade nothing that depends on it.'),
  ('heattransfer', 'intermediate', 'final', null, 37, 'A tube side is declared as condensing. How does the engine answer?', '["It refuses at length, saying the condensing exponent is not established here.", "It answers with the heating form and attaches a warning to the number.", "With a short refusal naming heating as the only service it carries.", "It answers, because condensation is what the laminar limit describes."]'::jsonb, 2, 'This module carries no form for condensation at all, and it says so in its own description. The cooled tube side is the other refusal on that door, and that one states the size of what it is declining to guess.'),
  ('heattransfer', 'intermediate', 'final', null, 38, 'A screen prints a film coefficient computed at one tube count beside a different count. What does that tell you?', '["The film was computed at a seed on the ladder rather than at the answer.", "The count was rounded up twice and the film was taken before the second rounding.", "The film belongs to the clean coefficient and the count to the dirty one.", "One of the two numbers was never computed, and the loop has not closed."]'::jsonb, 3, 'The fix is to close the loop rather than to choose a better constant. At the converged count the duty, the coefficient, the area and the driving force satisfy the equation they were built from.'),
  ('heattransfer', 'intermediate', 'final', null, 39, 'At 60 tubes the studio film is 647.823324 with a U dirty of 95.098250, and at 74 tubes they are 547.762384 and 92.110348. Which pair belongs to this exchanger?', '["The pair at 60 tubes, because the higher film is the better machine.", "The pair at 74 tubes, because that is the count the loop settled on.", "Either pair, since both are engine answers.", "Neither pair, because the film at this tier arrives typed rather than computed."]'::jsonb, 1, 'The rows above the last one are the trail the iteration left behind. Two tubes at the top of that trail give a film of 9843.591536, which belongs to a bundle nobody would build.'),
  ('heattransfer', 'intermediate', 'final', null, 40, 'Why can moving the tube count change which resistance is named as controlling?', '["The reference area moves with the count, so every term is rescaled.", "The declared threshold is measured against the count in that answer.", "The inside film moves with the count, and the inside film is one of the five.", "The fouling allowances are converted by a ratio that follows the count."]'::jsonb, 2, 'The stack was assembled at particular flows, allowances and a tube count, and each of those is an input a reader can change. The verdict belongs to the case rather than to the exchanger.'),
  ('heattransfer', 'intermediate', 'final', null, 41, 'The studio case is sized at a correction of 1.000000, and the correction door returns 0.964693 on the same four temperatures. What separates the two?', '["The second belongs to a one shell pass and two tube pass unit, and the case as sized is counter-current.", "The second is the equivalent single-shell value, and the first is the whole unit value.", "The second was computed at the converged tube count and the first at the seed.", "The second carries the steep-curve warning and the first does not."]'::jsonb, 0, 'The arrangement is an input, and the correction is what a shell and tube unit pays for running partly in parallel flow. A counter-current case has nothing to correct.'),
  ('heattransfer', 'intermediate', 'final', null, 42, 'Which of these does this engine leave to another module entirely?', '["The overall coefficient referred to the outside surface.", "The pressure drop along the tube side.", "The correction factor at a stated shell pass count.", "The inside film coefficient in the turbulent regime."]'::jsonb, 1, 'Pressure drop in a line belongs to the Pipeline and Line Sizing engine and machine work belongs to Rotating Equipment. The shell side film stays an input here as well, because a rigorous one needs stream analysis that belongs in a dedicated rating package.');
